import { actions, afterMount, connect, kea, listeners, MakeLogicType, path, selectors } from 'kea'
import { router } from 'kea-router'
import type { LocationChangedPayload } from 'kea-router/lib/types'
import posthog from 'posthog-js'

import { FEATURE_FLAGS } from 'lib/constants'
import { featureFlagLogic, FeatureFlagsSet } from 'lib/logic/featureFlagLogic'
import { appLogic } from 'scenes/appLogic'
import { urls } from 'scenes/urls'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface adventCalendarAccessLogicValues {
    featureFlagsTimedOut: boolean // appLogic
    featureFlags: FeatureFlagsSet // featureFlagLogic
    receivedFeatureFlags: boolean // featureFlagLogic
    flagsSettled: boolean
    hasCalendar: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface adventCalendarAccessLogicActions {
    leaveWithoutCalendar: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface adventCalendarAccessLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        hasCalendar: (featureFlags: FeatureFlagsSet) => boolean
        flagsSettled: (receivedFeatureFlags: boolean, featureFlagsTimedOut: boolean) => boolean
    }
    __keaTypeGenInternalReducerActions: {
        'location changed (kea.router)': ({
            method,
            pathname,
            search,
            searchParams,
            hash,
            hashParams,
            initial,
            url,
            routerState,
        }: LocationChangedPayload) => {
            payload: {
                hash: string
                hashParams: Record<string, any>
                initial: boolean
                method: 'POP' | 'PUSH' | 'REPLACE'
                pathname: string
                routerState: Record<string, any>
                search: string
                searchParams: Record<string, any>
                url: string
            }
            type: 'location changed (kea.router)'
        }
    }
}

export type adventCalendarAccessLogicType = MakeLogicType<
    adventCalendarAccessLogicValues,
    adventCalendarAccessLogicActions,
    Record<string, any>,
    adventCalendarAccessLogicMeta
>

const calendarRoute = (pathname: string): string => {
    try {
        return decodeURI(pathname).replace(/\/+$/, '')
    } catch {
        return pathname
    }
}

export const adventCalendarAccessLogic = kea<adventCalendarAccessLogicType>([
    path(['products', 'workflows', 'frontend', 'AdventCalendar', 'adventCalendarAccessLogic']),
    connect(() => ({
        values: [featureFlagLogic, ['featureFlags', 'receivedFeatureFlags'], appLogic, ['featureFlagsTimedOut']],
    })),
    actions({
        leaveWithoutCalendar: true,
    }),
    selectors({
        hasCalendar: [
            (s) => [s.featureFlags],
            (featureFlags: adventCalendarAccessLogicValues['featureFlags']) =>
                !!featureFlags[FEATURE_FLAGS.WORKFLOWS_ADVENT_CALENDAR],
        ],
        flagsSettled: [
            (s) => [s.receivedFeatureFlags, s.featureFlagsTimedOut],
            (
                receivedFeatureFlags: adventCalendarAccessLogicValues['receivedFeatureFlags'],
                featureFlagsTimedOut: adventCalendarAccessLogicValues['featureFlagsTimedOut']
            ): boolean => receivedFeatureFlags || featureFlagsTimedOut,
        ],
    }),
    listeners(({ actions, values, cache }) => ({
        leaveWithoutCalendar: async (_, breakpoint) => {
            await posthog.featureFlags?.reloadFeatureFlagsAsync()
            breakpoint()
            const stillOnCalendar = calendarRoute(router.values.location.pathname) === calendarRoute(cache.calendarPath)
            if (!values.hasCalendar && stillOnCalendar) {
                router.actions.replace(urls.workflows())
            }
        },
        [router.actionTypes.locationChanged]: () => {
            if (values.flagsSettled && !values.hasCalendar) {
                actions.leaveWithoutCalendar()
            }
        },
    })),
    afterMount(({ cache }) => {
        cache.calendarPath = router.values.location.pathname
    }),
])
